def _payload(self, target, evidence_ids, *, full=False, memory_ids=None):
    ids = set(evidence_ids)
    if not ids <= self.evidence.keys():
        raise ContractError('session_unknown_evidence')
    selected = self.checkpoint.sources if full else tuple((s for s in self.checkpoint.sources if any((self.evidence[i].source_id == s.source_id for i in ids))))
    allowed_sources = {s.source_id for s in selected}
    for source in selected:
        for (index, message) in enumerate(source.messages):
            if message.content:
                bound = bind_span(source, index, 0, len(message.content))
                self.evidence[bound.id] = bound
    visible = set(self._nodes()) if full else set(memory_ids or ())
    return dict(target=target, sources=[s.model_dump(mode='json') for s in selected], evidence=[e.model_dump(mode='json') for e in self.evidence.values() if e.source_id in allowed_sources], memory=[n.model_dump(mode='json') for n in self.state.nodes if n.id in visible], graph=[e.model_dump(mode='json') for e in self.state.edges if e.upstream in visible and e.downstream in visible])

